var t=`1092-beef-lok-lak`;var n=`world-1092`;var a=`KH`;var s=`southeast-asia`;var o=4;var r=54;var l={en:`Beef Lok Lak`,ua:`Яловичина лок лак`};var g={en:`Beef Lok Lak is a dish from Cambodia prepared with beef sirloin, oyster sauce, light soy sauce, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Яловичина лок лак, страва кухні країни Камбоджа, яку готують із таких продуктів: яловичий сирлойн, устричний соус, світлий соєвий соус, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`beef-sirloin`,750,`g`],[`oyster-sauce`,35,`ml`],[`light-soy-sauce`,32,`ml`],[`garlic`,4,`clove`],[`ground-black-pepper`,6,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`canola-oil`,45,`ml`],[`red-onion`,160,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`lime-juice`,45,`ml`],[`ground-black-pepper`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`tomato`,220,`g`],[`cucumber`,200,`g`],[`lettuce`,190,`g`]]}];var u={slug:t,id:n,country:`KH`,region:s,servings:4,minutes:54,title:l,text:g,steps:d};export{a as country,u as default,n as id,r as minutes,s as region,o as servings,t as slug,d as steps,g as text,l as title};